import { Link } from "react-router-dom";
import "../Styles/Home.css";
import Footer from "./Footer";

const Home = () => {
  return (
    <div className="home-container">
      {/* ===== Hero Section ===== */}
      <section className="hero-section">
        <h1 className="hero-title">
          Unlock Your Potential.{" "}
          <span className="highlight">Power UTAS Businesses.</span>
        </h1>

        <p className="hero-subtext">
          Connect ambitious students with Dhofar companies and ministries for
          flexible, part-time work. Training options are available for
          newcomers.
        </p>
        <Link to="/studentlogin">
          <button className="get-start-btn">Get Start</button>
        </Link>
      </section>

      {/* ===== Footer ===== */}
      <Footer />
    </div>
  );
};

export default Home;
